/// Reference documentation for application programming interfaces (APIs).
@Schema(description: 'Reference documentation for application programming interfaces (APIs).')
abstract class APIReference implements TechArticle, $Thing {
  /// Library file name, e.g., mscorlib.dll, system.web.dll.
  @StringField(name: 'assembly')
  String? get assembly;

  /// Associated product/technology version. E.g., .NET Framework 4.5.
  @StringField(name: 'assemblyVersion')
  String? get assemblyVersion;

  /// Library file name, e.g., mscorlib.dll, system.web.dll.
  @StringField(name: 'executableLibraryName')
  String? get executableLibraryName;

  /// Indicates whether API is managed or unmanaged.
  @StringField(name: 'programmingModel')
  String? get programmingModel;

  /// Type of app development: phone, Metro style, desktop, XBox, etc.
  @StringField(name: 'targetPlatform')
  String? get targetPlatform;

}

