  @AnyOf([PropertyValue, String])
  @JsonKey(name: 'hasRepresentation', includeIfNull: false)
  Object? get hasRepresentation;

  /// Another BioChemEntity encoding by this one.
  @JsonKey(name: 'isEncodedByBioChemEntity', includeIfNull: false)
  Gene? get isEncodedByBioChemEntity;

  /// Biological process this BioChemEntity is involved in; please use PropertyValue if you want to include any evidence.
  @AnyOf([DefinedTerm, PropertyValue, String])
  @JsonKey(name: 'isInvolvedInBiologicalProcess', includeIfNull: false)
