/// A book.
@Schema(description: 'A book.')
abstract class Book implements CreativeWork, $Thing {
  /// Indicates whether the book is an abridged edition.
  @JsonKey(name: 'abridged', includeIfNull: false)
  bool? get abridged;

  /// The edition of the book.
  @StringField(name: 'bookEdition')
  String? get bookEdition;

  /// The format of the book.
  @StringField(name: 'bookFormat', enumValues: ['AudiobookFormat', 'EBook', 'GraphicNovel', 'Hardcover', 'Pamphlet', 'Paperback'])
  String? get bookFormat;

  /// The illustrator of the book.
  @JsonKey(name: 'illustrator', includeIfNull: false)
  Person? get illustrator;

  /// The ISBN of the book.
  @StringField(name: 'isbn')
  String? get isbn;

  /// The number of pages in the book.
  @IntegerField(name: 'numberOfPages')
  int? get numberOfPages;

}

