  /// The unique address by which the BroadcastService can be identified in a provider lineup. In US, this is typically a number.
  @StringField(name: 'broadcastChannelId')
  String? get broadcastChannelId;

  /// The frequency used for over-the-air broadcasts. Numeric values or simple ranges, e.g. 87-99. In addition a shortcut idiom is supported for frequencies of AM and FM radio channels, e.g. "87 FM".
  @AnyOf([BroadcastFrequencySpecification, String])
  @JsonKey(name: 'broadcastFrequency', includeIfNull: false)
  Object? get broadcastFrequency;

  /// The type of service required to have access to the channel (e.g. Standard or Premium).
  @StringField(name: 'broadcastServiceTier')
  String? get broadcastServiceTier;

  /// Genre of the creative work, broadcast channel or group.
  @AnyOf([DefinedTerm, String])
  @JsonKey(name: 'genre', includeIfNull: false)
  Object? get genre;

  /// The CableOrSatelliteService offering the channel.
  @JsonKey(name: 'inBroadcastLineup', includeIfNull: false)
  CableOrSatelliteService? get inBroadcastLineup;

  /// The BroadcastService offered on this channel.
  @JsonKey(name: 'providesBroadcastService', includeIfNull: false)
  BroadcastService? get providesBroadcastService;

}

