/// A country.
@Schema(description: 'A country.')
abstract class Country implements AdministrativeArea, $Thing {
}

class CountryData extends DynamicSchemaThing implements Country {
  const CountryData({super.context, super.type = 'Country', required super.rawJson});

  factory CountryData.fromJson(Map<String, dynamic> json) => CountryData(
        context: json['@context'] as String?,
        type: json['@type'] != null ? SchemaOrg.normalizeType(json['@type'].toString()) : 'Country',
        rawJson: Map<String, dynamic>.unmodifiable(json),
      );

  @override
  PropertyValue? get additionalProperty {
