  @AnyOf([DefinedTerm, String])
  @JsonKey(name: 'educationalLevel', includeIfNull: false)
  Object? get educationalLevel;

  /// The purpose of a work in the context of education; for example, 'assignment', 'group work'.
  @AnyOf([DefinedTerm, String])
  @JsonKey(name: 'educationalUse', includeIfNull: false)
