/// A date value in [ISO 8601 date format](http://en.wikipedia.org/wiki/ISO_8601).
@Schema(description: 'A date value in [ISO 8601 date format](http://en.wikipedia.org/wiki/ISO_8601).')
abstract class Date implements $Thing {
}

class DateData extends DynamicSchemaThing implements Date {
  const DateData({super.context, super.type = 'Date', required super.rawJson});

  factory DateData.fromJson(Map<String, dynamic> json) => DateData(
        context: json['@context'] as String?,
        type: json['@type'] != null ? SchemaOrg.normalizeType(json['@type'].toString()) : 'Date',
        rawJson: Map<String, dynamic>.unmodifiable(json),
      );

}

