/// An airline flight.
@Schema(description: 'An airline flight.')
abstract class Flight implements Trip, $Thing {
  /// The kind of aircraft (e.g., "Boeing 747").
  @AnyOf([String, Vehicle])
  @JsonKey(name: 'aircraft', includeIfNull: false)
  Object? get aircraft;

  /// The airport where the flight terminates.
  @JsonKey(name: 'arrivalAirport', includeIfNull: false)
  Airport? get arrivalAirport;

  /// Identifier of the flight's arrival gate.
  @StringField(name: 'arrivalGate')
  String? get arrivalGate;

  /// Identifier of the flight's arrival terminal.
  @StringField(name: 'arrivalTerminal')
  String? get arrivalTerminal;

  /// The type of boarding policy used by the airline (e.g. zone-based or group-based).
  @StringField(name: 'boardingPolicy', enumValues: ['GroupBoardingPolicy', 'ZoneBoardingPolicy'])
  String? get boardingPolicy;

  /// 'carrier' is an out-dated term indicating the 'provider' for parcel delivery and flights.
  @JsonKey(name: 'carrier', includeIfNull: false)
  Organization? get carrier;

  /// The airport where the flight originates.
  @JsonKey(name: 'departureAirport', includeIfNull: false)
  Airport? get departureAirport;

  /// Identifier of the flight's departure gate.
  @StringField(name: 'departureGate')
  String? get departureGate;

  /// Identifier of the flight's departure terminal.
  @StringField(name: 'departureTerminal')
  String? get departureTerminal;

  /// The estimated time the flight will take.
  @AnyOf([SchemaDuration, String])
  @JsonKey(name: 'estimatedFlightDuration', includeIfNull: false)
  Object? get estimatedFlightDuration;

  /// The distance of the flight.
  @AnyOf([Distance, String])
  @JsonKey(name: 'flightDistance', includeIfNull: false)
  Object? get flightDistance;

  /// The unique identifier for a flight including the airline IATA code. For example, if describing United flight 110, where the IATA code for United is 'UA', the flightNumber is 'UA110'.
  @StringField(name: 'flightNumber')
  String? get flightNumber;

  /// Description of the meals that will be provided or available for purchase.
  @StringField(name: 'mealService')
  String? get mealService;

  /// An entity which offers (sells / leases / lends / loans) the services / goods.  A seller may also be a provider.
  @AnyOf([Organization, Person])
  @JsonKey(name: 'seller', includeIfNull: false)
  Object? get seller;

  /// The time when a passenger can check into the flight online.
  @StringField(name: 'webCheckinTime', format: 'date-time')
  String? get webCheckinTime;

}

