/// An image file.
@Schema(description: 'An image file.')
abstract class ImageObject implements MediaObject, $Thing {
  /// The caption for this object. For downloadable machine formats (closed caption, subtitles etc.) use MediaObject and indicate the [[encodingFormat]].
  @AnyOf([MediaObject, String])
  @JsonKey(name: 'caption', includeIfNull: false)
  Object? get caption;

  /// Represents textual captioning from a [[MediaObject]], e.g. text of a 'meme'.
  @StringField(name: 'embeddedTextCaption')
  String? get embeddedTextCaption;

  /// exif data for this object.
  @AnyOf([PropertyValue, String])
  @JsonKey(name: 'exifData', includeIfNull: false)
  Object? get exifData;

  /// Indicates whether this image is representative of the content of the page.
  @JsonKey(name: 'representativeOfPage', includeIfNull: false)
  bool? get representativeOfPage;

}

