/// A single message from a sender to one or more organizations or people.
@Schema(description: 'A single message from a sender to one or more organizations or people.')
abstract class Message implements CreativeWork, $Thing {
  /// A sub property of recipient. The recipient blind copied on a message.
  @AnyOf([ContactPoint, Organization, Person])
  @JsonKey(name: 'bccRecipient', includeIfNull: false)
  Object? get bccRecipient;

  /// A sub property of recipient. The recipient copied on a message.
  @AnyOf([ContactPoint, Organization, Person])
  @JsonKey(name: 'ccRecipient', includeIfNull: false)
  Object? get ccRecipient;

  /// The date/time at which the message has been read by the recipient if a single recipient exists.
  @StringField(name: 'dateRead', format: 'date-time')
  String? get dateRead;

  /// The date/time the message was received if a single recipient exists.
  @StringField(name: 'dateReceived', format: 'date-time')
  String? get dateReceived;

  /// The date/time at which the message was sent.
  @StringField(name: 'dateSent', format: 'date-time')
  String? get dateSent;

  /// A CreativeWork attached to the message.
  @JsonKey(name: 'messageAttachment', includeIfNull: false)
  CreativeWork? get messageAttachment;

  /// A sub property of participant. The participant who is at the receiving end of the action.
  @AnyOf([Audience, ContactPoint, Organization, Person])
  @JsonKey(name: 'recipient', includeIfNull: false)
  Object? get recipient;

  /// A sub property of participant. The participant who is at the sending end of the action.
  @AnyOf([Audience, Organization, Person])
  @JsonKey(name: 'sender', includeIfNull: false)
  Object? get sender;

  /// A sub property of recipient. The recipient who was directly sent the message.
  @AnyOf([Audience, ContactPoint, Organization, Person])
  @JsonKey(name: 'toRecipient', includeIfNull: false)
  Object? get toRecipient;

}

