/// A collection of music tracks in playlist form.
@Schema(description: 'A collection of music tracks in playlist form.')
abstract class MusicPlaylist implements CreativeWork, $Thing {
  /// The number of tracks in this album or playlist.
  @IntegerField(name: 'numTracks')
  int? get numTracks;

  /// A music recording (track)&#x2014;usually a single song. If an ItemList is given, the list should contain items of type MusicRecording.
  @AnyOf([ItemList, MusicRecording])
  @JsonKey(name: 'track', includeIfNull: false)
  Object? get track;

  /// A music recording (track)&#x2014;usually a single song.
  @JsonKey(name: 'tracks', includeIfNull: false)
  MusicRecording? get tracks;

}

