/// Data type: Number.\n\nUsage guidelines:\n\n* Use values from 0123456789 (Unicode 'DIGIT ZERO' (U+0030) to 'DIGIT NINE' (U+0039)) rather than superficially similar Unicode symbols.\n* Use '.' (Unicode 'FULL STOP' (U+002E)) rather than ',' to indicate a decimal point. Avoid using these symbols as a readability separator.
@Schema(description: 'Data type: Number.\\n\\nUsage guidelines:\\n\\n* Use values from 0123456789 (Unicode \'DIGIT ZERO\' (U+0030) to \'DIGIT NINE\' (U+0039)) rather than superficially similar Unicode symbols.\\n* Use \'.\' (Unicode \'FULL STOP\' (U+002E)) rather than \',\' to indicate a decimal point. Avoid using these symbols as a readability separator.')
abstract class Number implements $Thing {
}

class NumberData extends DynamicSchemaThing implements Number {
  const NumberData({super.context, super.type = 'Number', required super.rawJson});

  factory NumberData.fromJson(Map<String, dynamic> json) => NumberData(
        context: json['@context'] as String?,
        type: json['@type'] != null ? SchemaOrg.normalizeType(json['@type'].toString()) : 'Number',
        rawJson: Map<String, dynamic>.unmodifiable(json),
      );

}

/// Nutritional information about the recipe.
@Schema(description: 'Nutritional information about the recipe.')
abstract class NutritionInformation implements StructuredValue, $Thing {
  /// The number of calories.
  @JsonKey(name: 'calories', includeIfNull: false)
  Energy? get calories;

  /// The number of grams of carbohydrates.
  @JsonKey(name: 'carbohydrateContent', includeIfNull: false)
  Mass? get carbohydrateContent;

  /// The number of milligrams of cholesterol.
  @JsonKey(name: 'cholesterolContent', includeIfNull: false)
  Mass? get cholesterolContent;

  /// The number of grams of fat.
  @JsonKey(name: 'fatContent', includeIfNull: false)
  Mass? get fatContent;

  /// The number of grams of fiber.
  @JsonKey(name: 'fiberContent', includeIfNull: false)
  Mass? get fiberContent;

  /// The number of grams of protein.
  @JsonKey(name: 'proteinContent', includeIfNull: false)
  Mass? get proteinContent;

  /// The number of grams of saturated fat.
  @JsonKey(name: 'saturatedFatContent', includeIfNull: false)
  Mass? get saturatedFatContent;

  /// The serving size, in terms of the number of volume or mass.
  @StringField(name: 'servingSize')
  String? get servingSize;

  /// The number of milligrams of sodium.
  @JsonKey(name: 'sodiumContent', includeIfNull: false)
  Mass? get sodiumContent;

  /// The number of grams of sugar.
  @JsonKey(name: 'sugarContent', includeIfNull: false)
  Mass? get sugarContent;

  /// The number of grams of trans fat.
  @JsonKey(name: 'transFatContent', includeIfNull: false)
  Mass? get transFatContent;

  /// The number of grams of unsaturated fat.
  @JsonKey(name: 'unsaturatedFatContent', includeIfNull: false)
  Mass? get unsaturatedFatContent;

