/// A permit issued by an organization, e.g. a parking pass.
@Schema(description: 'A permit issued by an organization, e.g. a parking pass.')
abstract class Permit implements Intangible, $Thing {
  /// The organization issuing the item, for example a [[Permit]], [[Ticket]], or [[Certification]].
  @JsonKey(name: 'issuedBy', includeIfNull: false)
  Organization? get issuedBy;

  /// The service through which the permit was granted.
  @JsonKey(name: 'issuedThrough', includeIfNull: false)
  Service? get issuedThrough;

  /// The target audience for this permit.
  @JsonKey(name: 'permitAudience', includeIfNull: false)
  Audience? get permitAudience;

  /// The duration of validity of a permit or similar thing.
  @JsonKey(name: 'validFor', includeIfNull: false)
  SchemaDuration? get validFor;

  /// The date when the item becomes valid.
  @StringField(name: 'validFrom', format: 'date-time')
  String? get validFrom;

  /// The geographic area where the item is valid. Applies for example to a [[Permit]], a [[Certification]], or an [[EducationalOccupationalCredential]].
  @JsonKey(name: 'validIn', includeIfNull: false)
  AdministrativeArea? get validIn;

  /// The date when the item is no longer valid.
  @StringField(name: 'validUntil', format: 'date')
  String? get validUntil;

}

