/// A software application.
@Schema(description: 'A software application.')
abstract class SoftwareApplication implements CreativeWork, $Thing {
  /// Type of software application, e.g. 'Game, Multimedia'.
  @StringField(name: 'applicationCategory', format: 'uri')
  String? get applicationCategory;

  /// Subcategory of the application, e.g. 'Arcade Game'.
  @StringField(name: 'applicationSubCategory', format: 'uri')
  String? get applicationSubCategory;

  /// The name of the application suite to which the application belongs (e.g. Excel belongs to Office).
  @StringField(name: 'applicationSuite')
  String? get applicationSuite;

  /// Device required to run the application. Used in cases where a specific make/model is required to run the application.
  @StringField(name: 'availableOnDevice')
  String? get availableOnDevice;

  /// Countries for which the application is not supported. You can also provide the two-letter ISO 3166-1 alpha-2 country code.
  @StringField(name: 'countriesNotSupported')
  String? get countriesNotSupported;

  /// Countries for which the application is supported. You can also provide the two-letter ISO 3166-1 alpha-2 country code.
  @StringField(name: 'countriesSupported')
  String? get countriesSupported;

  /// Device required to run the application. Used in cases where a specific make/model is required to run the application.
  @StringField(name: 'device')
  String? get device;

  /// If the file can be downloaded, URL to download the binary.
  @StringField(name: 'downloadUrl', format: 'uri')
  String? get downloadUrl;

  /// Features or modules provided by this application (and possibly required by other applications).
  @StringField(name: 'featureList', format: 'uri')
  String? get featureList;

  /// Size of the application / package (e.g. 18MB). In the absence of a unit (MB, KB etc.), KB will be assumed.
  @StringField(name: 'fileSize')
  String? get fileSize;

  /// URL at which the app may be installed, if different from the URL of the item.
  @StringField(name: 'installUrl', format: 'uri')
  String? get installUrl;

  /// Minimum memory requirements.
  @StringField(name: 'memoryRequirements', format: 'uri')
  String? get memoryRequirements;

  /// Operating systems supported (Windows 7, OS X 10.6, Android 1.6).
  @AnyOf([OperatingSystem, String])
  @JsonKey(name: 'operatingSystem', includeIfNull: false)
  Object? get operatingSystem;

  /// Permission(s) required to run the app (for example, a mobile app may require full internet access or may run only on wifi).
  @StringField(name: 'permissions')
  String? get permissions;

  /// Processor architecture required to run the application (e.g. IA64).
  @StringField(name: 'processorRequirements')
  String? get processorRequirements;

  /// Description of what changed in this version.
  @StringField(name: 'releaseNotes', format: 'uri')
  String? get releaseNotes;

  /// Component dependency requirements for application. This includes runtime environments and shared libraries that are not included in the application distribution package, but required to run the application (examples: DirectX, Java or .NET runtime).
  @StringField(name: 'requirements', format: 'uri')
  String? get requirements;

  /// Runtime platform or script interpreter dependencies (example: Java v1, Python 2.3, .NET Framework 3.0).
  @AnyOf([RuntimePlatform, String])
  @JsonKey(name: 'runtimePlatform', includeIfNull: false)
  Object? get runtimePlatform;

  /// A link to a screenshot image of the app.
  @AnyOf([ImageObject, String])
  @JsonKey(name: 'screenshot', includeIfNull: false)
  Object? get screenshot;

  /// Additional content for a software application.
  @JsonKey(name: 'softwareAddOn', includeIfNull: false)
  SoftwareApplication? get softwareAddOn;

  /// Software application help.
  @JsonKey(name: 'softwareHelp', includeIfNull: false)
  CreativeWork? get softwareHelp;

  /// Component dependency requirements for application. This includes runtime environments and shared libraries that are not included in the application distribution package, but required to run the application (examples: DirectX, Java or .NET runtime).
  @AnyOf([SoftwareApplication, String])
  @JsonKey(name: 'softwareRequirements', includeIfNull: false)
  Object? get softwareRequirements;

  /// Version of the software instance.
  @StringField(name: 'softwareVersion')
  String? get softwareVersion;

  /// Storage requirements (free space required).
  @StringField(name: 'storageRequirements', format: 'uri')
  String? get storageRequirements;

  /// Supporting data for a SoftwareApplication.
  @JsonKey(name: 'supportingData', includeIfNull: false)
  DataFeed? get supportingData;

}

