/// Event type: Sports event.
@Schema(description: 'Event type: Sports event.')
abstract class SportsEvent implements Event, $Thing {
  /// The away team in a sports event.
  @AnyOf([Person, SportsTeam])
  @JsonKey(name: 'awayTeam', includeIfNull: false)
  Object? get awayTeam;

  /// A competitor in a sports event.
  @AnyOf([Person, SportsTeam])
  @JsonKey(name: 'competitor', includeIfNull: false)
  Object? get competitor;

  /// The home team in a sports event.
  @AnyOf([Person, SportsTeam])
  @JsonKey(name: 'homeTeam', includeIfNull: false)
  Object? get homeTeam;

  /// An official who watches a game or match closely to enforce the rules and arbitrate on matters arising from the play such as referees, umpires or judges. The name of the effective function can vary according to the sport.
  @JsonKey(name: 'referee', includeIfNull: false)
  Person? get referee;

  /// A type of sport (e.g. Baseball).
  @StringField(name: 'sport', format: 'uri')
  String? get sport;

}

