/// A table on a Web page.
@Schema(description: 'A table on a Web page.')
abstract class Table implements WebPageElement, $Thing {
}

class TableData extends DynamicSchemaThing implements Table {
  const TableData({super.context, super.type = 'Table', required super.rawJson});

