/// A set of organisms asserted to represent a natural cohesive biological unit.
@Schema(description: 'A set of organisms asserted to represent a natural cohesive biological unit.')
abstract class Taxon implements Thing, $Thing {
  /// Closest child taxa of the taxon in question.
  @AnyOf([Taxon, String])
  @JsonKey(name: 'childTaxon', includeIfNull: false)
  Object? get childTaxon;

  /// A Defined Term contained in this term set.
  @JsonKey(name: 'hasDefinedTerm', includeIfNull: false)
  DefinedTerm? get hasDefinedTerm;

  /// Closest parent taxon of the taxon in question.
  @AnyOf([Taxon, String])
  @JsonKey(name: 'parentTaxon', includeIfNull: false)
  Object? get parentTaxon;

  /// The taxonomic rank of this taxon given preferably as a URI from a controlled vocabulary – typically the ranks from TDWG TaxonRank ontology or equivalent Wikidata URIs.
  @AnyOf([PropertyValue, String])
  @JsonKey(name: 'taxonRank', includeIfNull: false)
  Object? get taxonRank;

}

