/// The most generic type of item.
@Schema(description: 'The most generic type of item.')
abstract class Thing implements $Thing {
  /// An additional type for the item, typically used for adding more specific types from external vocabularies in microdata syntax. This is a relationship between something and a class that the thing is in. Typically the value is a URI-identified RDF class, and in this case corresponds to the
  /// use of rdf:type in RDF. Text values can be used sparingly, for cases where useful information can be added without their being an appropriate schema to reference. In the case of text values, the class label should follow the schema.org <a href="https://schema.org/docs/styleguide.html">style guide</a>.
  @StringField(name: 'additionalType', format: 'uri')
  String? get additionalType;

  /// An alias for the item.
  @StringField(name: 'alternateName')
  String? get alternateName;

  /// A description of the item.
  @AnyOf([String, TextObject])
  @JsonKey(name: 'description', includeIfNull: false)
  Object? get description;

  /// A sub property of description. A short description of the item used to disambiguate from other, similar items. Information from other properties (in particular, name) may be necessary for the description to be useful for disambiguation.
  @StringField(name: 'disambiguatingDescription')
  String? get disambiguatingDescription;

  /// The identifier property represents any kind of identifier for any kind of [[Thing]], such as ISBNs, GTIN codes, UUIDs etc. Schema.org provides dedicated properties for representing many of these, either as textual strings or as URL (URI) links. See [background notes](/docs/datamodel.html#identifierBg) for more details.
  ///
  @AnyOf([PropertyValue, String])
  @JsonKey(name: 'identifier', includeIfNull: false)
  Object? get identifier;

  /// An image of the item. This can be a [[URL]] or a fully described [[ImageObject]].
  @AnyOf([ImageObject, String])
  @JsonKey(name: 'image', includeIfNull: false)
  Object? get image;

  /// Indicates a page (or other CreativeWork) for which this thing is the main entity being described. See [background notes](/docs/datamodel.html#mainEntityBackground) for details.
  @AnyOf([CreativeWork, String])
  @JsonKey(name: 'mainEntityOfPage', includeIfNull: false)
  Object? get mainEntityOfPage;

  /// The name of the item.
  @StringField(name: 'name')
  String? get name;

  /// A person or organization who owns this Thing.
  @AnyOf([Organization, Person])
  @JsonKey(name: 'owner', includeIfNull: false)
  Object? get owner;

  /// Indicates a potential Action, which describes an idealized action in which this thing would play an 'object' role.
  @JsonKey(name: 'potentialAction', includeIfNull: false)
  Action? get potentialAction;

  /// URL of a reference Web page that unambiguously indicates the item's identity. E.g. the URL of the item's Wikipedia page, Wikidata entry, or official website.
  @StringField(name: 'sameAs', format: 'uri')
  String? get sameAs;

  /// A CreativeWork or Event about this Thing.
  @AnyOf([CreativeWork, Event])
  @JsonKey(name: 'subjectOf', includeIfNull: false)
  Object? get subjectOf;

  /// URL of the item.
  @StringField(name: 'url', format: 'uri')
  String? get url;

}

class ThingData extends DynamicSchemaThing implements Thing {
  const ThingData({super.context, super.type = 'Thing', required super.rawJson});

  factory ThingData.fromJson(Map<String, dynamic> json) => ThingData(
        context: json['@context'] as String?,
        type: json['@type'] != null ? SchemaOrg.normalizeType(json['@type'].toString()) : 'Thing',
        rawJson: Map<String, dynamic>.unmodifiable(json),
      );

  @override
