/// Used to describe a ticket to an event, a flight, a bus ride, etc.
@Schema(description: 'Used to describe a ticket to an event, a flight, a bus ride, etc.')
abstract class Ticket implements Intangible, $Thing {
  /// The date the ticket was issued.
  @StringField(name: 'dateIssued', format: 'date-time')
  String? get dateIssued;

  /// The organization issuing the item, for example a [[Permit]], [[Ticket]], or [[Certification]].
  @JsonKey(name: 'issuedBy', includeIfNull: false)
  Organization? get issuedBy;

  /// The currency of the price, or a price component when attached to [[PriceSpecification]] and its subtypes.\n\nUse standard formats: [ISO 4217 currency format](http://en.wikipedia.org/wiki/ISO_4217), e.g. "USD"; [Ticker symbol](https://en.wikipedia.org/wiki/List_of_cryptocurrencies) for cryptocurrencies, e.g. "BTC"; well known names for [Local Exchange Trading Systems](https://en.wikipedia.org/wiki/Local_exchange_trading_system) (LETS) and other currency types, e.g. "Ithaca HOUR".
  @StringField(name: 'priceCurrency')
  String? get priceCurrency;

  /// The unique identifier for the ticket.
  @StringField(name: 'ticketNumber')
  String? get ticketNumber;

  /// Reference to an asset (e.g., Barcode, QR code image or PDF) usable for entrance.
  @StringField(name: 'ticketToken', format: 'uri')
  String? get ticketToken;

  /// The seat associated with the ticket.
  @JsonKey(name: 'ticketedSeat', includeIfNull: false)
  Seat? get ticketedSeat;

  /// The total price for the reservation or ticket, including applicable taxes, shipping, etc.\n\nUsage guidelines:\n\n* Use values from 0123456789 (Unicode 'DIGIT ZERO' (U+0030) to 'DIGIT NINE' (U+0039)) rather than superficially similar Unicode symbols.\n* Use '.' (Unicode 'FULL STOP' (U+002E)) rather than ',' to indicate a decimal point. Avoid using these symbols as a readability separator.
  @AnyOf([double, PriceSpecification, String])
  @JsonKey(name: 'totalPrice', includeIfNull: false)
  Object? get totalPrice;

  /// The person or organization the reservation or ticket is for.
  @AnyOf([Organization, Person])
  @JsonKey(name: 'underName', includeIfNull: false)
  Object? get underName;

}

