  @StringField(name: 'priceType', enumValues: ['InvoicePrice', 'ListPrice', 'MSRP', 'MaximumRetailPrice', 'MinimumAdvertisedPrice', 'RegularPrice', 'SRP', 'SalePrice', 'StrikethroughPrice'])
